#include <WiFi.h>
#include <esp_now.h>
#include <esp_wifi.h>

// =====================================================
// LEFT BTS7960
// =====================================================

#define LEFT_R_EN   27
#define LEFT_L_EN   14
#define LEFT_RPWM   25
#define LEFT_LPWM   26

// =====================================================
// RIGHT BTS7960
// =====================================================

#define RIGHT_R_EN  33
#define RIGHT_L_EN  32
#define RIGHT_RPWM  18
#define RIGHT_LPWM  19

// =====================================================
// SPEED
// =====================================================

#define PWM_FREQ 20000
#define PWM_RES  8

// =====================================================
// SAFETY
// =====================================================

// If the controller stops communicating for this long,
// the car stops automatically.

#define COMMUNICATION_TIMEOUT 500

unsigned long lastCommandTime = 0;

// =====================================================
// CONTROLLER ADDRESS
// =====================================================

uint8_t controllerAddress[6];

bool controllerFound = false;

// =====================================================
// COMMAND PACKET
// =====================================================

struct CommandPacket {
  char command;
  uint8_t speed;
};

// =====================================================
// STOP MOTORS
// =====================================================

void stopMotors() {

  ledcWrite(LEFT_RPWM, 0);
  ledcWrite(LEFT_LPWM, 0);

  ledcWrite(RIGHT_RPWM, 0);
  ledcWrite(RIGHT_LPWM, 0);
}

// =====================================================
// FORWARD
// =====================================================

void forward(uint8_t speed) {

  ledcWrite(LEFT_RPWM, speed);
  ledcWrite(LEFT_LPWM, 0);

  ledcWrite(RIGHT_RPWM, speed);
  ledcWrite(RIGHT_LPWM, 0);
}

// =====================================================
// REVERSE
// =====================================================

void reverse(uint8_t speed) {

  ledcWrite(LEFT_RPWM, 0);
  ledcWrite(LEFT_LPWM, speed);

  ledcWrite(RIGHT_RPWM, 0);
  ledcWrite(RIGHT_LPWM, speed);
}

// =====================================================
// TURN LEFT
// =====================================================

void turnLeft(uint8_t speed) {

  // Left side backwards
  ledcWrite(LEFT_RPWM, 0);
  ledcWrite(LEFT_LPWM, speed);

  // Right side forwards
  ledcWrite(RIGHT_RPWM, speed);
  ledcWrite(RIGHT_LPWM, 0);
}

// =====================================================
// TURN RIGHT
// =====================================================

void turnRight(uint8_t speed) {

  // Left side forwards
  ledcWrite(LEFT_RPWM, speed);
  ledcWrite(LEFT_LPWM, 0);

  // Right side backwards
  ledcWrite(RIGHT_RPWM, 0);
  ledcWrite(RIGHT_LPWM, speed);
}

// =====================================================
// ADD CONTROLLER AS PEER
// =====================================================

bool addController() {

  if (esp_now_is_peer_exist(controllerAddress)) {
    return true;
  }

  esp_now_peer_info_t peerInfo = {};

  memcpy(
    peerInfo.peer_addr,
    controllerAddress,
    6
  );

  peerInfo.channel = 1;
  peerInfo.encrypt = false;

  if (esp_now_add_peer(&peerInfo) != ESP_OK) {

    Serial.println("Could not add controller");

    return false;
  }

  return true;
}

// =====================================================
// RECEIVE DATA
// =====================================================

void onDataReceive(
  const esp_now_recv_info_t *info,
  const uint8_t *data,
  int len
) {

  // ---------------------------------------------------
  // CONTROLLER IS LOOKING FOR THE CAR
  // ---------------------------------------------------

  if (len >= 5 && memcmp(data, "HELLO", 5) == 0) {

    memcpy(
      controllerAddress,
      info->src_addr,
      6
    );

    controllerFound = addController();

    if (controllerFound) {

      Serial.println();
      Serial.println("================================");
      Serial.println("CONTROLLER FOUND!");
      Serial.println("================================");

      // Tell controller that this is the car

      const char reply[] = "CAR";

      esp_now_send(
        controllerAddress,
        (uint8_t *)reply,
        sizeof(reply)
      );
    }

    return;
  }

  // ---------------------------------------------------
  // COMMAND FROM CONTROLLER
  // ---------------------------------------------------

  if (!controllerFound) {
    return;
  }

  if (len != sizeof(CommandPacket)) {
    return;
  }

  CommandPacket packet;

  memcpy(
    &packet,
    data,
    sizeof(packet)
  );

  lastCommandTime = millis();

  // ---------------------------------------------------
  // EXECUTE COMMAND
  // ---------------------------------------------------

  switch (packet.command) {

    case 'F':

      forward(packet.speed);

      Serial.println("FORWARD");
      break;

    case 'B':

      reverse(packet.speed);

      Serial.println("REVERSE");
      break;

    case 'L':

      turnLeft(packet.speed);

      Serial.println("LEFT");
      break;

    case 'R':

      turnRight(packet.speed);

      Serial.println("RIGHT");
      break;

    case 'S':

      stopMotors();

      Serial.println("STOP");
      break;

    default:

      stopMotors();

      Serial.println("UNKNOWN COMMAND");
      break;
  }
}

// =====================================================
// SETUP
// =====================================================

void setup() {

  Serial.begin(115200);

  // ---------------------------------------------------
  // ENABLE PINS
  // ---------------------------------------------------

  pinMode(LEFT_R_EN, OUTPUT);
  pinMode(LEFT_L_EN, OUTPUT);

  pinMode(RIGHT_R_EN, OUTPUT);
  pinMode(RIGHT_L_EN, OUTPUT);

  digitalWrite(LEFT_R_EN, HIGH);
  digitalWrite(LEFT_L_EN, HIGH);

  digitalWrite(RIGHT_R_EN, HIGH);
  digitalWrite(RIGHT_L_EN, HIGH);

  // ---------------------------------------------------
  // PWM
  // ---------------------------------------------------

  ledcAttach(
    LEFT_RPWM,
    PWM_FREQ,
    PWM_RES
  );

  ledcAttach(
    LEFT_LPWM,
    PWM_FREQ,
    PWM_RES
  );

  ledcAttach(
    RIGHT_RPWM,
    PWM_FREQ,
    PWM_RES
  );

  ledcAttach(
    RIGHT_LPWM,
    PWM_FREQ,
    PWM_RES
  );

  stopMotors();

  // ---------------------------------------------------
  // WIFI / ESP-NOW
  // ---------------------------------------------------

  WiFi.mode(WIFI_STA);

  // Both ESP32s use channel 1

  esp_wifi_set_channel(
    1,
    WIFI_SECOND_CHAN_NONE
  );

  Serial.println();
  Serial.println("================================");
  Serial.println("ESP32 CAR");
  Serial.println("================================");

  Serial.print("Car MAC: ");
  Serial.println(WiFi.macAddress());

  if (esp_now_init() != ESP_OK) {

    Serial.println("ESP-NOW FAILED!");

    stopMotors();

    while (true) {
      delay(1000);
    }
  }

  esp_now_register_recv_cb(onDataReceive);

  Serial.println("ESP-NOW READY");
  Serial.println("Waiting for controller...");

  lastCommandTime = millis();
}

// =====================================================
// MAIN LOOP
// =====================================================

void loop() {

  // ---------------------------------------------------
  // SAFETY TIMEOUT
  // ---------------------------------------------------

  if (
    controllerFound &&
    millis() - lastCommandTime > COMMUNICATION_TIMEOUT
  ) {

    stopMotors();

    controllerFound = false;

    Serial.println("CONTROLLER LOST - STOPPING");
    Serial.println("Waiting for controller...");
  }

  delay(10);
}
